def by_phase(phase: str) -> tuple[DatasetSpec, ...]:
    return tuple(item for item in DATASETS if item.phase == phase)


def by_key(key: str) -> DatasetSpec:
    for item in DATASETS:
        if item.key == key:
            return item
    raise KeyError(key)
